import{_ as l,o,c as i,a2 as a}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"lifecycle","description":"","frontmatter":{"layout":"doc","title":"lifecycle"},"headers":[],"relativePath":"vue/lifecycle.md","filePath":"vue/lifecycle.md"}'),t={name:"vue/lifecycle.md"};function d(c,e,u,r,n,s){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="option-api-中的生命周期钩子函数" tabindex="-1">Option Api 中的生命周期钩子函数 <a class="header-anchor" href="#option-api-中的生命周期钩子函数" aria-label="Permalink to &quot;Option Api 中的生命周期钩子函数&quot;">​</a></h1><p>在 Vue 2.x 和 Vue 3 的 Options API 中，生命周期钩子的使用方式基本保持一致。Vue 的生命周期可以分为三个阶段：创建阶段、挂载阶段、更新阶段、销毁阶段。</p><h2 id="vue2与vue3中生命周期钩子函数的对比" tabindex="-1">vue2与vue3中生命周期钩子函数的对比 <a class="header-anchor" href="#vue2与vue3中生命周期钩子函数的对比" aria-label="Permalink to &quot;vue2与vue3中生命周期钩子函数的对比&quot;">​</a></h2><h3 id="vue2中生命周期钩子函数" tabindex="-1">vue2中生命周期钩子函数 <a class="header-anchor" href="#vue2中生命周期钩子函数" aria-label="Permalink to &quot;vue2中生命周期钩子函数&quot;">​</a></h3><ol><li>创建阶段 <ul><li><code>beforeCreate</code>: 在实例初始化之后，数据观测 (data observer) 和事件配置之前被调用。</li><li><code>created</code>: 在实例创建完成后被立即调用。在这一步，实例已完成对数据的观测，但是尚未挂载 DOM。</li></ul></li><li>挂载阶段 <ul><li><code>beforeMount</code>: 在挂载开始之前被调用。在这一步，实例已完成对数据的观测，但是尚未挂载 DOM。</li><li><code>mounted</code>: 在挂载完成后调用。在这一步，实例已完成对数据的观测，并且 DOM 也已挂载。</li></ul></li><li>更新阶段 <ul><li><code>beforeUpdate</code>: 在数据更新时调用，发生在虚拟 DOM 打补丁之前。</li><li><code>updated</code>: 在数据更新后调用，发生在虚拟 DOM 打补丁之后。</li></ul></li><li>销毁阶段 <ul><li><code>beforeDestroy</code>: 在实例销毁之前调用。在这一步，实例仍然完全可用。</li><li><code>destroyed</code>: 在实例销毁后调用。调用后，Vue 实例指示的所有东西都会解绑定，所有的事件监听器会被移除，所有的子实例也会被销毁。</li></ul></li></ol><h3 id="vue3中生命周期钩子函数" tabindex="-1">vue3中生命周期钩子函数 <a class="header-anchor" href="#vue3中生命周期钩子函数" aria-label="Permalink to &quot;vue3中生命周期钩子函数&quot;">​</a></h3><ol><li>创建阶段 <ul><li><code>setup</code>: 在实例初始化之前调用。在这一步，实例尚未创建，但是可以访问到 props、context 等参数。</li></ul></li><li>挂载阶段 <ul><li><code>onBeforeMount</code>: 在挂载开始之前被调用。在这一步，实例已完成对数据的观测，但是尚未挂载 DOM。</li><li><code>onMounted</code>: 在挂载完成后调用。在这一步，实例已完成对数据的观测，并且 DOM 也已挂载。</li></ul></li><li>更新阶段 <ul><li><code>onBeforeUpdate</code>: 在数据更新时调用，发生在虚拟 DOM 打补丁之前。</li><li><code>onUpdated</code>: 在数据更新后调用，发生在虚拟 DOM 打补丁之后。</li></ul></li><li>销毁阶段 <ul><li><code>onBeforeUnmount</code>: 在实例销毁之前调用。在这一步，实例仍然完全可用。</li><li><code>onUnmounted</code>: 在实例销毁后调用。调用后，Vue 实例指示的所有东西都会解绑定，所有的事件监听器会被移除，所有的子实例也会被销毁。</li></ul></li></ol><h2 id="生命周期的使用" tabindex="-1">生命周期的使用 <a class="header-anchor" href="#生命周期的使用" aria-label="Permalink to &quot;生命周期的使用&quot;">​</a></h2>',8)])])}const f=l(t,[["render",d]]);export{h as __pageData,f as default};
